import unittest
from candidate import count_distinct_characters


class TestCountDistinctCharacters(unittest.TestCase):
    def test_normal_string_distinct_chars(self):
        self.assertEqual(count_distinct_characters('abc'), 3)

    def test_all_same_characters(self):
        self.assertEqual(count_distinct_characters('aaaa'), 1)

    def test_mixed_case_same_char(self):
        self.assertEqual(count_distinct_characters('xyzXYZ'), 3)

    def test_mixed_case_different_chars(self):
        self.assertEqual(count_distinct_characters('Jerry'), 4)

    def test_single_character(self):
        self.assertEqual(count_distinct_characters('a'), 1)

    def test_single_uppercase_character(self):
        self.assertEqual(count_distinct_characters('A'), 1)

    def test_empty_string(self):
        self.assertEqual(count_distinct_characters(''), 0)

    def test_case_insensitive_a_and_A(self):
        self.assertEqual(count_distinct_characters('aA'), 1)

    def test_case_insensitive_all_pairs(self):
        self.assertEqual(count_distinct_characters('aAbBcC'), 3)

    def test_with_spaces(self):
        self.assertEqual(count_distinct_characters('a b c'), 4)

    def test_only_spaces(self):
        self.assertEqual(count_distinct_characters('   '), 1)

    def test_with_numbers(self):
        self.assertEqual(count_distinct_characters('a1b2c3'), 6)

    def test_with_special_characters(self):
        self.assertEqual(count_distinct_characters('a!b@c#'), 6)

    def test_with_punctuation(self):
        self.assertEqual(count_distinct_characters('.,;:'), 4)

    def test_repeated_mixed_case(self):
        self.assertEqual(count_distinct_characters('AaAaAa'), 1)

    def test_full_alphabet(self):
        self.assertEqual(count_distinct_characters('abcdefghijklmnopqrstuvwxyz'), 26)

    def test_full_alphabet_mixed_case(self):
        self.assertEqual(count_distinct_characters('AbCdEfGhIjKlMnOpQrStUvWxYz'), 26)

    def test_with_newline_and_tab(self):
        self.assertEqual(count_distinct_characters('a\nb\tc'), 5)

    def test_unicode_characters(self):
        self.assertEqual(count_distinct_characters('éèê'), 3)

    def test_none_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            count_distinct_characters(None)

    def test_integer_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            count_distinct_characters(123)

    def test_list_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            count_distinct_characters(['a', 'b', 'c'])

    def test_returns_integer_type(self):
        self.assertIsInstance(count_distinct_characters('abc'), int)

    def test_all_26_letters_uppercase(self):
        self.assertEqual(count_distinct_characters('ABCDEFGHIJKLMNOPQRSTUVWXYZ'), 26)

    def test_repeated_distinct_chars(self):
        self.assertEqual(count_distinct_characters('aabbccee'), 3)

    def test_single_repeated_char_100_times(self):
        self.assertEqual(count_distinct_characters('x' * 100), 1)

    def test_all_alphanumeric_distinct(self):
        self.assertEqual(count_distinct_characters('aB1!'), 4)

    def test_none_char_in_string(self):
        self.assertEqual(count_distinct_characters('a\0b'), 3)


if __name__ == '__main__':
    unittest.main()
